require __DIR__.'/../app/bootstrap.php';
try{validateCsrf();$u=requireUser([],true);throttle('password',(string)$u['ID_Usuario'],8);$old=passwordInput('actual',1,200);$new=passwordInput('nueva',8);if($new!==passwordInput('confirmar',1))throw new DomainException('Las contraseñas no coinciden.');
transaction(function()use($u,$old,$new){$r=one('SELECT * FROM usuario WHERE ID_Usuario=? FOR UPDATE',[(int)$u['ID_Usuario']]);if(!password_verify($old,$r['Contrasena']))throw new DomainException('Contraseña actual incorrecta.');if(password_verify($new,$r['Contrasena']))throw new DomainException('La nueva contraseña debe ser diferente.');requireStrongPassword($new,[$r['Nombre'],$r['Usuario'],$r['Correo']??'']);query('UPDATE usuario SET Contrasena=?,cambiar_clave=0,sesion_version=sesion_version+1 WHERE ID_Usuario=?',[password_hash($new,PASSWORD_DEFAULT),(int)$u['ID_Usuario']]);query("UPDATE recuperacion SET estado='Cancelada',token_hash=NULL WHERE ID_Usuario=? AND usado IS NULL",[(int)$u['ID_Usuario']]);audit($u,'CAMBIAR_CLAVE','usuario',(int)$u['ID_Usuario']);$_SESSION['sesion_version']=(int)$r['sesion_version']+1;});session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(32));reply(['ok'=>true,'redirect'=>url(homeFor($u))]);}catch(Throwable $ex){errorReply($ex);}
